@js:
if(/\/users\//.test(baseUrl)){
	result = java.getString("@tag.a.0@href")
	} else if (baseUrl.includes("view_adult=true")) {
		 	result = baseUrl.replace(/(works\/\d+).*/, "$1/chapters/"+java.getString("@value") +"\?view_adult=true")
} else if(baseUrl.match(/\d+/)){
